mapper.select:
SELECT

FROM t_app_feedback f
LEFT JOIN t_wx_member m ON m.member_id = f.member_id
LEFT JOIN t_employee e ON e.employee_id = f.reply_member_id

    f.deleted_flag = 0

        AND (
            f.content LIKE CONCAT('%', #{query.searchWord}, '%')
            OR m.nickname LIKE CONCAT('%', #{query.searchWord}, '%')
            OR CAST(f.feedback_id AS CHAR) = #{query.searchWord}
        )


        AND f.type = #{query.type}


        AND f.status = #{query.status}


        AND f.member_id = #{query.memberId}


        AND f.create_time >= #{query.beginDate}


        AND f.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)



    ORDER BY f.feedback_id DESC
